<?php
use App\Actions\SaveProject;
use App\Livewire\AdminComponent;
use App\Models\Project;
use Illuminate\Support\Str;
use Livewire\Attributes\Layout;
use Livewire\Attributes\Locked;
new #[Layout('layouts::admin')] class extends AdminComponent {
    #[Locked] public ?int $recordId=null;
    public array $form=['title'=>'','slug'=>'','category'=>'residential','location'=>'','year'=>null,'summary'=>'','story'=>'','approach'=>'','services_text'=>'','materials_text'=>'','cover_asset'=>'','status'=>'draft','featured'=>false,'is_demo'=>false];
    public function mount(?string $slug=null):void{if($slug){$project=Project::where('slug',$slug)->firstOrFail();$this->recordId=$project->id;foreach(array_keys($this->form) as $key){if(!in_array($key,['services_text','materials_text']))$this->form[$key]=$project->$key;}foreach(['services','materials'] as $field)$this->form[$field.'_text']=implode("\n",$project->$field??[]);}}
    public function updatedFormTitle():void{if(!$this->recordId)$this->form['slug']=Str::slug($this->form['title']);}
    public function save():void{$project=app(SaveProject::class)->handle($this->form,$this->recordId?Project::findOrFail($this->recordId):null);session()->flash('status','Project saved.');if(!$this->recordId)$this->redirectRoute('admin.projects.edit',['slug'=>$project->slug]);}
};
?>
<div><header class="admin-page-heading"><div><a class="text-link" href="{{ route('admin.projects') }}">← All projects</a><h1>{{ $recordId?'Edit the project':'A new story' }}</h1><p>Publish actual commissions with your own images. Keep concept studies clearly labelled.</p></div></header>@if(session('status'))<p class="admin-flash" role="status">{{ session('status') }}</p>@endif @if($errors->any())<div class="form-errors" role="alert">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif<form wire:submit="save" class="admin-editor-form"><section class="admin-panel"><h2>The project</h2><div class="form-pair"><label>Title<input wire:model.live.debounce.300ms="form.title" maxlength="160" required></label><label>URL slug<input wire:model="form.slug" maxlength="180" required></label></div><div class="form-triple"><label>Category<select wire:model="form.category"><option value="residential">Residential</option><option value="commercial">Commercial</option><option value="styling">Styling & finishing</option></select></label><label>Location <small>(optional)</small><input wire:model="form.location" maxlength="100"></label><label>Year <small>(optional)</small><input type="number" wire:model="form.year" min="1900" max="{{ now()->year+1 }}"></label></div><label>Short introduction<textarea wire:model="form.summary" rows="2" maxlength="600"></textarea></label><label>The story<textarea wire:model="form.story" rows="7" maxlength="20000"></textarea></label><label>The approach<textarea wire:model="form.approach" rows="5" maxlength="12000"></textarea></label><div class="form-pair"><label>Services <small>(one per line)</small><textarea wire:model="form.services_text" rows="5"></textarea></label><label>Materials <small>(one per line)</small><textarea wire:model="form.materials_text" rows="5"></textarea></label></div></section><section class="admin-panel"><h2>Publication</h2><div class="form-pair"><label>Status<select wire:model="form.status"><option value="draft">Draft — private</option><option value="published">Published — public</option></select></label><label class="admin-check"><input type="checkbox" wire:model="form.featured">Feature on the homepage</label></div><label class="admin-check"><input type="checkbox" wire:model.live="form.is_demo">This is a concept study, not a completed commission</label>@if($form['is_demo'])<label>Concept cover<select wire:model="form.cover_asset"><option value="">Soft geometry</option><option value="assets/soft-geometry.webp">Soft geometry</option><option value="assets/the-social-room.webp">The social room</option><option value="assets/city-apartment.webp">City apartment</option></select></label>@endif<button class="solid-button" type="submit" wire:loading.attr="disabled">Save project<x-grei.icon name="check" /></button></section></form>@if($recordId)<livewire:admin.media-manager type="project" :record-id="$recordId" />@endif</div>
